import{_ as e,o as d,c as r,a2 as o}from"./chunks/framework.SkWZtmk2.js";const m=JSON.parse('{"title":"简介","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md"}'),a={name:"guide/introduction.md"};function i(n,t,c,h,l,s){return d(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h1><p>Print Studio 用于制作可编辑的打印模板，注入业务数据后生成 HTML、PDF，或调用浏览器预览与打印。提供可视化设计器与纯代码 API 两条路径：既可以让用户在设计器里编辑模板，也可以完全通过代码创建模板并输出。</p><h2 id="设计目标与核心价值" tabindex="-1">设计目标与核心价值 <a class="header-anchor" href="#设计目标与核心价值" aria-label="Permalink to &quot;设计目标与核心价值&quot;">​</a></h2><p>围绕「模板与数据分离」组织全部能力：模板 JSON 由设计器或代码维护，业务数据在打印时注入。</p><ul><li><strong>业务解耦</strong>：格式调整只改模板，不改动业务代码；数据结构变化只影响绑定路径。</li><li><strong>一套模型、多种输出</strong>：设计器与输出共用同一份文档模型，预览、浏览器打印、HTML 与 PDF 走同一条渲染管线。</li><li><strong>嵌入即用</strong>：宿主页面零样式接入。</li></ul><p>能力清单、典型场景与能力边界见 <a href="./capabilities.html">核心能力与使用场景</a>。</p><h2 id="环境与兼容性" tabindex="-1">环境与兼容性 <a class="header-anchor" href="#环境与兼容性" aria-label="Permalink to &quot;环境与兼容性&quot;">​</a></h2><ul><li><strong>运行环境</strong>：现代浏览器（Chrome / Edge / Firefox / Safari）；不支持 Node SSR。</li><li><strong>模块格式</strong>：纯 ESM 包，不提供 CommonJS 接入。</li></ul><p>安装与兼容细节见<a href="./getting-started.html">快速上手</a>。</p><h2 id="与常见替代方案的差异" tabindex="-1">与常见替代方案的差异 <a class="header-anchor" href="#与常见替代方案的差异" aria-label="Permalink to &quot;与常见替代方案的差异&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>典型限制</th><th>Print Studio 的做法</th></tr></thead><tbody><tr><td>服务端渲染打印</td><td>依赖后端环境与部署链路，预览受制于接口往返</td><td>全流程在浏览器内完成，无服务端依赖，调整模板即时预览</td></tr><tr><td>手写 HTML / CSS 模板</td><td>无可视化设计器，坐标、分页与数据注入各自实现</td><td>统一 mm 坐标体系、文档展开与自动分页，模板与数据分离</td></tr><tr><td>自研打印组件</td><td>需自行维护渲染、分页、导出与扩展机制</td><td>输出管线、注册表扩展与插件系统开箱即用，模板 JSON 自主可控</td></tr></tbody></table><p>Print Studio 不负责模板与业务数据的持久化：模板 JSON 存储由 <code>onSave</code> / <code>storage</code> 选项对接，打印数据由每次输出时的 <code>input</code> 传入。</p><h2 id="三种使用形态" tabindex="-1">三种使用形态 <a class="header-anchor" href="#三种使用形态" aria-label="Permalink to &quot;三种使用形态&quot;">​</a></h2><table tabindex="0"><thead><tr><th>形态</th><th>入口</th><th>适用场景</th></tr></thead><tbody><tr><td>可视化编辑</td><td><code>useDesigner()</code> + <code>&lt;PrintDesigner&gt;</code> 或 <code>createDesigner()</code> + <code>studio.mount({ el })</code></td><td>让用户在设计器里编辑模板</td></tr><tr><td>代码编辑 + 输出</td><td><code>createDesigner()</code>（不挂载视图）</td><td>业务代码创建 / 修改模板，直接输出</td></tr><tr><td>纯输出</td><td><code>createPrinter()</code></td><td>已有模板 JSON，只注入数据输出</td></tr></tbody></table><p>形态之间只是「谁来创建模板、要不要视图」的差别。</p><h2 id="创建方式" tabindex="-1">创建方式 <a class="header-anchor" href="#创建方式" aria-label="Permalink to &quot;创建方式&quot;">​</a></h2><p>前两种形态都需要先创建 Designer 实例。按宿主环境选择创建方式：</p><table tabindex="0"><thead><tr><th>创建方式</th><th>来源</th><th>适用场景</th></tr></thead><tbody><tr><td><code>createDesigner(options?)</code></td><td><code>@printstack/print-studio</code></td><td>纯代码创建实例，拥有全部编辑与输出能力；需要界面时再调用 <code>studio.mount({ el })</code> 挂载</td></tr><tr><td><code>attachDesigner(container, options?)</code></td><td><code>@printstack/print-studio/designer</code></td><td>非 Vue 宿主一次性挂载设计器：同步返回 <code>{ ready, studio, unmount }</code> 句柄，<code>ready</code> resolve 即界面与插件就绪；未传 <code>studio</code> 时自建实例，<code>unmount()</code> 时一并销毁</td></tr><tr><td><code>useDesigner()</code> + <code>&lt;PrintDesigner&gt;</code></td><td><code>@printstack/print-studio/vue</code></td><td>Vue 组件树集成：组合式函数创建实例并随 Vue 作用域销毁自动清理，组件负责渲染视图与生命周期</td></tr></tbody></table><p>三种方式得到同一套实例 API，差异只在生命周期归属：<code>createDesigner()</code> 由持有方自行 <code>dispose()</code>；<code>attachDesigner()</code> 的生命周期跟随句柄；<code>useDesigner()</code> 跟随 Vue 作用域。详见 <a href="./../reference/vue-designer.html">Vue 集成</a>与 <a href="./../reference/studio.html">createDesigner()</a>。</p><h2 id="按任务查找" tabindex="-1">按任务查找 <a class="header-anchor" href="#按任务查找" aria-label="Permalink to &quot;按任务查找&quot;">​</a></h2><table tabindex="0"><thead><tr><th>任务</th><th>推荐入口</th></tr></thead><tbody><tr><td>接入业务系统的全套流程</td><td><a href="./getting-started.html">快速上手</a></td></tr><tr><td>从零系统学习库集成</td><td><a href="./../tutorial/">循序渐进教程</a></td></tr><tr><td>只用代码完成「建模板 → 打印 → 导出」全流程</td><td><a href="./workflow.html">完整接入流程</a></td></tr><tr><td>将其他设计器的模板转换为本系统格式</td><td><a href="./template-format.html">模板格式与迁移</a></td></tr><tr><td>查询实例的方法、参数和返回值</td><td><a href="./../reference/studio.html">createDesigner() 参考</a></td></tr><tr><td>查询元素的属性（文本 / 表格 / 条形码等）</td><td><a href="./../reference/element-text.html">内置元素</a></td></tr><tr><td>注入业务数据、格式化、循环明细</td><td><a href="./../reference/data-binding.html">数据绑定</a></td></tr><tr><td>预览窗口、打印行为与导出选项</td><td><a href="./../reference/output.html">预览 / 打印 / 导出</a></td></tr><tr><td>已有模板 JSON 直接输出，不加载编辑界面</td><td><a href="./../reference/renderer.html">createPrinter</a></td></tr><tr><td>商品标签、快递面单等案例</td><td><a href="./../examples/product-label.html">业务案例</a></td></tr><tr><td>在线修改并运行示例代码</td><td><a href="../playground/index.html" target="_blank">在线 Playground</a></td></tr><tr><td>排查安装、空白页、保存与数据问题</td><td><a href="./troubleshooting.html">常见问题</a></td></tr></tbody></table><h2 id="四个核心对象" tabindex="-1">四个核心对象 <a class="header-anchor" href="#四个核心对象" aria-label="Permalink to &quot;四个核心对象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对象</th><th>说明</th><th>常见操作</th></tr></thead><tbody><tr><td><code>studio</code></td><td>Designer 实例的业务操作入口</td><td><code>studio.document.loadJson(json)</code></td></tr><tr><td>打印文档 <code>PrintDocument</code></td><td>可保存为 JSON 的模板模型，含页面、元素与绑定配置</td><td><code>studio.document.data</code> 读取快照</td></tr><tr><td>打印数据 <code>input</code></td><td>本次输出的客户、订单、明细等数据</td><td><code>studio.preview({ customer: { name: &#39;张女士&#39; } })</code></td></tr><tr><td><code>PrintDesigner</code></td><td>连接实例的 Vue 可视化设计器组件</td><td><code>&lt;PrintDesigner :studio=&quot;studio&quot; /&gt;</code></td></tr></tbody></table><p>「打印模板」是整个可复用文档；「页面模板」是页面共用的页眉、页脚、背景（<code>studio.template</code> 管理）。打印数据不会写回模板；HTML / PDF 是输出结果，不能当作可编辑 JSON 加载。</p><h2 id="基本约定" tabindex="-1">基本约定 <a class="header-anchor" href="#基本约定" aria-label="Permalink to &quot;基本约定&quot;">​</a></h2><ul><li>位置、尺寸、边距单位 <strong>mm</strong>；字号 <strong>pt</strong>；旋转<strong>度</strong>；页面左上角为坐标原点，y 向下。</li><li><code>data</code> 是快照：修改快照不会编辑文档，更新必须走句柄或集合方法。</li><li>查询缺失对象返回 <code>undefined</code>；句柄在对象删除后其 <code>data</code> 也可能为 <code>undefined</code>；加载另一份文档后重新查询句柄。</li><li>模板渲染依赖浏览器环境，不支持 Node.js 服务端渲染（SSR）。</li></ul>',26)])])}const g=e(a,[["render",i]]);export{m as __pageData,g as default};
